select
    id,workorder_id,order_type,customer_name,order_code,workorder_code,equipment_id,equipment_code,axle_number,wire_disc,plant_name,product_id,specification,model,weight,measure_id,measure_name,disc_number,start_time,end_time,sort,remark,is_deleted,version,create_by,create_time,update_by,update_time,status,attr1,attr2,attr3,enamelling_code,insert_id,insert_model,insert_workorder,insert_status,plant_number,wire_disc_number,wight_completion,degree_of_completion,standard_name,standard_value,wire_disc_id
from mes_enamelling_workorder

    is_deleted = 0
