     and sort = #{sort}
     and remark = #{remark}
     and is_deleted = #{isDeleted}
     and version = #{version}
     and create_by = #{createBy}
     and create_time = #{createTime}
     and update_by = #{updateBy}
     and update_time = #{updateTime}
     and status = #{status}
     and attr1 = #{attr1}
     and attr2 = #{attr2}
     and attr3 = #{attr3}
     and enamelling_code = #{enamellingCode}
     and product_id = #{productId}
     and insert_id = #{insertId}
     and insert_model = #{insertModel}
     and insert_workorder = #{insertWorkorder}
     and insert_status = #{insertStatus}
     and plant_number = #{plantNumber}
     and wire_disc_number = #{wireDiscNumber}
     and wight_completion = #{wightCompletion}
     and degree_of_completion = #{degreeOfCompletion}
     and standard_name = #{standardName}
     and standard_value = #{standardValue}
     and wire_disc_id = #{wireDiscId}

        AND date_format(create_time,'%y%m%d') >= date_format(#{params.beginTime},'%y%m%d')


        AND date_format(create_time,'%y%m%d') <= date_format(#{params.endTime},'%y%m%d')


    ${params.dataScope}

order by status asc,sort desc,create_time desc

